{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C32"],
      "claim": "Trazodone, the highest-transfer analogue, has absolute oral bioavailability of 70–90% in humans, directly supporting F ≥20% for a similarly sized heteroaromatic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Alprazolam, a closely transferring lipophilic heterocycle, shows absolute oral bioavailability generally exceeding 90% in humans, supporting high oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C19"],
      "claim": "Flibanserin, despite being among the lower-bioavailability analogues, still has an estimated absolute oral bioavailability of 45.9%, above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C47"],
      "claim": "Tolfenamic acid, a low-molecular-weight drug with high transferability, has absolute oral bioavailability averaging 60% in healthy volunteers, supporting F ≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "Triazolam, a structurally related triazolobenzodiazepine, has an estimated absolute oral bioavailability of 0.55 in humans, still well above the 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All transferable experimental evidence from high-scoring analogues indicates oral bioavailability well above 20% (roughly 33–100%), with no contradictory evidence; the physicochemical prior is also favorable. Therefore the query is predicted high.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for aminopyrine itself was provided; inference relies on close analogues.",
    "First-pass metabolism or transporter-mediated clearance for the query is not directly measured, though analogues with similar features still exceed 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

